import * as React from 'react'

const Exists: React.FC = () => {
  return (
    <div className="w-full flex flex-col gap-2">
      <span>
        O operador EXISTS é usado para verificar se uma subconsulta retorna algum resultado. Ele
        retorna verdadeiro se a subconsulta produzir pelo menos um registro. Por exemplo, para
        listar os cursos que possuem alunos matriculados:
      </span>

      <span className="text-center">SELECT NomeCurso FROM Cursos</span>

      <span>
        WHERE EXISTS (SELECT * FROM Estudantes WHERE Estudantes.CursoID = Cursos.CursoID);
      </span>

      <span className="text-center">
        Essa abordagem é eficiente para confirmar a existência de relacionamentos entre tabelas.
      </span>
    </div>
  )
}

export default Exists
