import * as React from 'react'

const Some: React.FC = () => {
  return (
    <div className="w-full flex flex-col gap-2">
      <span>
        O operador SOME é usado para comparar um valor com os resultados de uma subconsulta. Ele
        verifica se algum valor da subconsulta satisfaz a condição. Por exemplo, para encontrar
        alunos com idades maiores do que pelo menos um dos valores na tabela IdadesPermitidas:
      </span>

      <span className="text-center">
        SELECT Nome FROM Estudantes WHERE Idade SOME (SELECT Idade FROM IdadesPermitidas);
      </span>

      <span>
        O SOME é equivalente a ANY no SQL e avalia a condição em relação a um conjunto de valores.
      </span>
    </div>
  )
}

export default Some
