import * as React from 'react'

const Update: React.FC = () => {
  return (
    <div className="w-full flex flex-col gap-2">
      <span>
        Subconsultas em comandos UPDATE permitem que você atualize dados em uma tabela com base nos
        resultados de uma consulta interna (subconsulta). Essa técnica é útil quando as alterações
        precisam considerar informações de outras tabelas ou agregações como média, soma, ou
        contagem de registros
      </span>

      <span>
        Quando combinadas com GROUP BY e ORDER BY, essas subconsultas oferecem mais controle,
        permitindo que você organize e agrupe os dados para identificar valores específicos a serem
        usados na atualização.
      </span>

      <span> Como funciona?</span>
      <span>
        - GROUP BY: Agrupa os registros com base em uma ou mais colunas e executa funções de
        agregação (e.g., AVG, SUM, COUNT) em cada grupo.
      </span>
      <span>
        - ORDER BY: Ordena os registros de acordo com uma ou mais colunas. Em comandos UPDATE, ele
        geralmente é usado dentro de uma subconsulta para selecionar valores específicos ordenados
        de maneira desejada.
      </span>

      <span>Exemplo Pratico</span>

      <span>
        Tabelas envolvidas: students: student_id: [1, 2, 3, 4] name: ['Ana', 'Carlos', 'João',
        'Maria'] score: [85, 70, 90, 88] exams: student_id: [1, 2, 3, 4] subject: ['Math', 'Math',
        'Math', 'Math'] exam_score: [85, 75, 95, 80]
      </span>

      <span>
        Objetivo: Atualizar a coluna score na tabela students com a média dos exam_score de cada
        aluno.
      </span>

      <span>
        Query com Subconsulta e GROUP BY: UPDATE students SET score = ( SELECT AVG(exam_score) FROM
        exams WHERE exams.student_id = students.student_id GROUP BY exams.student_id );
      </span>
    </div>
  )
}

export default Update
